              ".pm-wrap {\n  max-width: 1120px;\n}\n\n.pm-hero {\n  background: linear-gradient(135deg, #2859ff, #5a1ce2);\n  border-radius: 16px;\n  padding: 32px;\n  color: #fff;\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: space-between;\n  gap: 24px;\n  margin-bottom: 24px;\n}\n\n.pm-hero__content {\n  max-width: 560px;\n\n  h1 {\n    margin: 8px 0 12px;\n    font-size: 28px;\n\n    span {\n      display: inline-block;\n      background: linear-gradient(90deg, #ffffff, #dbeafe);\n      -webkit-background-clip: text;\n      -webkit-text-fill-color: transparent;\n    }\n  }\n\n  p {\n    margin: 0;\n    color: rgba(255, 255, 255, 0.9);\n  }\n}\n\n.pm-hero__eyebrow {\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  font-size: 12px;\n  margin: 0;\n}\n\n.pm-hero__meta {\n  display: flex;\n  gap: 8px;\n  margin-top: 16px;\n  font-size: 13px;\n  color: rgba(255, 255, 255, 0.85);\n}\n\n.pm-hero__actions {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  align-items: flex-start;\n\n  .pm-hero__actions-buttons {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 10px;\n  }\n}\n\n.pm-hero__note {\n  margin: 6px 0 0;\n  font-size: 13px;\n  color: rgba(255, 255, 255, 0.85);\n}\n\n.pm-btn {\n  border-radius: 999px;\n  padding: 10px 20px;\n  font-weight: 600;\n  border: none;\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  cursor: pointer;\n  transition: box-shadow 0.2s ease, transform 0.2s ease;\n  &.pm-btn--primary {\n    background: #fff;\n    color: #1d4ed8;\n    box-shadow: 0 8px 25px rgba(15, 23, 42, 0.2);\n  }\n\n  &.pm-btn--ghost {\n    background: rgba(255, 255, 255, 0.2);\n    color: #fff;\n    border: 1px solid rgba(255, 255, 255, 0.4);\n  }\n\n  &.pm-btn--outline {\n    background: transparent;\n    color: #fff;\n    border: 1px dashed rgba(255, 255, 255, 0.6);\n  }\n}\n\n.pm-btn:hover {\n  box-shadow: 0 12px 30px rgba(59, 130, 246, 0.35);\n  transform: translateY(-1px);\n}\n\n.pm-stat-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n  gap: 16px;\n  margin-bottom: 24px;\n}\n\n.pm-stat-card {\n  background: #fff;\n  border: 1px solid #e2e8f0;\n  border-radius: 16px;\n  padding: 20px;\n  box-shadow: 0 8px 30px rgba(24, 39, 75, 0.08);\n\n  &.tone-success {\n    border-color: #c6f6d5;\n    background: #f0fff4;\n  }\n\n  &.tone-warning {\n    border-color: #feebc8;\n    background: #fffaf0;\n  }\n\n  &.tone-info {\n    border-color: #bee3f8;\n    background: #ebf8ff;\n  }\n}\n\n.pm-stat-card__label {\n  display: block;\n  font-size: 12px;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  color: #718096;\n  margin-bottom: 6px;\n}\n\n.pm-stat-card__value {\n  display: block;\n  font-size: 22px;\n  font-weight: 600;\n  color: #1a202c;\n}\n\n.pm-stat-card__helper {\n  display: block;\n  font-size: 13px;\n  color: #718096;\n  margin-top: 6px;\n}\n\n.pm-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 4px 12px;\n  border-radius: 999px;\n  font-size: 13px;\n  font-weight: 600;\n  text-transform: capitalize;\n  background: #edf2f7;\n  color: #1a202c;\n\n  .dot {\n    width: 8px;\n    height: 8px;\n    border-radius: 50%;\n    background: currentColor;\n  }\n\n  &.status-running {\n    background: #e6fffa;\n    color: #0f766e;\n  }\n\n  &.status-pending {\n    background: #fefcbf;\n    color: #b45309;\n  }\n\n  &.status-completed {\n    background: #f0fff4;\n    color: #15803d;\n  }\n}\n\n.pm-help-callout {\n  background: #f8fafc;\n  border: 1px solid #dce3ef;\n  border-radius: 12px;\n  padding: 20px;\n  margin-bottom: 24px;\n  display: flex;\n  justify-content: space-between;\n  gap: 16px;\n  align-items: center;\n\n  p {\n    margin: 6px 0 0;\n    color: #4a5568;\n  }\n}\n\n.pm-post-type-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n  gap: 12px;\n}\n\n.pm-type-card {\n  border: 1px solid #e2e8f0;\n  border-radius: 16px;\n  background: #fff;\n  transition: border 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;\n  cursor: pointer;\n\n  &.pm-type-card--active {\n    border-color: #7c3aed;\n    box-shadow: 0 14px 35px rgba(80, 17, 204, 0.15);\n    transform: translateY(-2px);\n  }\n\n  .components-base-control {\n    margin: 0;\n  }\n}\n\n.pm-type-card__content {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.pm-type-card__indicator {\n  width: 36px;\n  height: 36px;\n  border-radius: 12px;\n  border: 1px solid #cbd5f5;\n  background: #f8fafc;\n}\n\n.pm-type-card--active .pm-type-card__indicator {\n  border-color: #7c3aed;\n  background: linear-gradient(135deg, #7c3aed, #4f46e5);\n}\n\n.pm-type-card__text {\n  flex: 1;\n}\n\n.pm-type-card__label {\n  font-size: 15px;\n  color: #111827;\n}\n\n.pm-type-card__slug {\n  display: block;\n  margin-top: 2px;\n  font-size: 12px;\n  color: #94a3b8;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n}\n\n.pm-checkbox-hidden {\n  position: relative;\n}\n\n.pm-checkbox-hidden .components-checkbox-control__input {\n  display: none;\n}\n\n.pm-checkbox-hidden .components-base-control__field {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip: rect(0 0 0 0);\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n.pm-status-message {\n  color: #475569;\n  margin-top: 8px;\n}\n\n.pm-last-run-list {\n  list-style: none;\n  padding: 0;\n  margin: 0 0 12px;\n}\n\n.pm-last-run-list li {\n  margin-bottom: 6px;\n}\n\n.pm-progress-panel {\n  background: #fff;\n  border: 1px solid #e2e8f0;\n  border-radius: 18px;\n  padding: 24px;\n  margin-top: 24px;\n  box-shadow: 0 20px 45px rgba(41, 72, 152, 0.12);\n}\n\n.pm-progress-panel__header {\n  display: flex;\n  justify-content: space-between;\n  align-items: flex-start;\n  gap: 16px;\n}\n\n.pm-progress-panel__eyebrow {\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  font-size: 11px;\n  margin: 0 0 6px;\n  color: #94a3b8;\n}\n\n.pm-progress-panel__meta {\n  margin-top: 4px;\n  color: #475569;\n}\n\n.pm-progressbar {\n  margin: 18px 0;\n  width: 100%;\n\n  .components-progress-bar__progress {\n    background: linear-gradient(90deg, #1d4ed8, #7c3aed);\n  }\n\n  &.pm-progressbar--animated .components-progress-bar__progress {\n    position: relative;\n    overflow: hidden;\n\n    &:before {\n      content: '';\n      position: absolute;\n      inset: 0;\n      background: linear-gradient(\n        120deg,\n        rgba(255, 255, 255, 0.15) 25%,\n        rgba(255, 255, 255, 0) 50%,\n        rgba(255, 255, 255, 0.15) 75%\n      );\n      animation: pm-progress-stripes 1.2s linear infinite;\n    }\n  }\n}\n\n.pm-progressbar.pm-progressbar--animated .components-progress-bar__progress:after {\n  display: none;\n}\n\n.pm-progressbar .components-progress-bar__track {\n  border-radius: 999px;\n  overflow: hidden;\n}\n\n.pm-progressbar .components-progress-bar__progress {\n  border-radius: 999px;\n}\n\n.pm-progress-panel__timeline {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));\n  gap: 12px;\n  margin-top: 12px;\n}\n\n.timeline-step {\n  border: 1px dashed #cbd5f5;\n  border-radius: 12px;\n  padding: 12px;\n\n  .dot {\n    display: inline-block;\n    width: 10px;\n    height: 10px;\n    border-radius: 50%;\n    background: #94a3b8;\n    margin-bottom: 6px;\n  }\n\n  &.active {\n    border-color: #a78bfa;\n\n    .dot {\n      background: #7c3aed;\n    }\n  }\n}\n\n.pm-history-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n  gap: 20px;\n  margin-top: 24px;\n}\n\n.pm-cli-box pre {\n  background: #0f172a;\n  color: #f1f5f9;\n  padding: 12px;\n  border-radius: 10px;\n  overflow: auto;\n  font-size: 13px;\n}\n\n@keyframes pm-progress-stripes {\n  from {\n    transform: translateX(-40%);\n  }\n\n  to {\n    transform: translateX(40%);\n  }\n}\n\n@media (max-width: 782px) {\n  .pm-hero {\n    padding: 24px;\n  }\n\n  .pm-hero__actions {\n    width: 100%;\n    flex-direction: row;\n    flex-wrap: wrap;\n  }\n\n  .pm-help-callout {\n    flex-direction: column;\n    align-items: flex-start;\n  }\n\n  .pm-progress-panel__header {\n    flex-direction: column;\n  }\n\n  .pm-history-grid {\n    grid-template-columns: 1fr;\n  }\n}\n"
